import{_ as i,a0 as l,w as r,s as p,ao as d,I as s,a1 as o,A as n,x as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Fedora 36 工作站中启用最小化和最大化按钮 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 36 工作站中启用最小化和最大化按钮 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 36 工作站中启用最小化和最大化按钮 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 36 工作站中启用最小化和最大化按钮 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220514 How To Enable Minimize And Maximize Buttons In Fedora 36 Workstation","title":"如何在 Fedora 36 工作站中启用最小化和最大化按钮","tag":"202205","desc":""},"relativePath":"202205/20220514 How To Enable Minimize And Maximize Buttons In Fedora 36 Workstation.md","filePath":"[post].md"}'),h={name:"202205/20220514 How To Enable Minimize And Maximize Buttons In Fedora 36 Workstation.md"};function m(u,e,g,b,x,f){const t=l("Link");return r(),p("div",null,[e[16]||(e[16]=d('<h1 id="如何在-fedora-36-工作站中启用最小化和最大化按钮" tabindex="-1">如何在 Fedora 36 工作站中启用最小化和最大化按钮 <a class="header-anchor" href="#如何在-fedora-36-工作站中启用最小化和最大化按钮" aria-label="Permalink to “如何在 Fedora 36 工作站中启用最小化和最大化按钮”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/22/151018fjxtiidtrztri0rr.jpg" alt=""></p><blockquote><p>今天，我们将看到 Fedora 桌面的安装后步骤之一。这个简短的指南解释了如何在 Fedora GNOME 工作站和 Silverblue 版本的应用窗口中启用最小化和最大化按钮。</p></blockquote><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>你可能已经知道，Fedora Silverblue 和 Fedora GNOME 工作站版本的应用窗口中没有最小化和最大化按钮。</p><p>如果要最小化应用窗口，需要右键单击其标题栏并从上下文菜单中选择最小化选项。</p><p>不幸的是，你甚至无法在 Firefox 中使用鼠标获得该选项。要最小化 Firefox 窗口，你要点击 <code>左 ALT+空格</code> 键并选择最小化选项。</p><p>我不知道隐藏最常用的按钮有什么好处。Ubuntu GNOME 桌面有最小/最大按钮，但 Fedora 没有。</p><p>如果你想恢复 Fedora GNOME 和 Silverblue 版本中的最小化和最大化按钮，你可以借助 Fedora 中的 <strong>Gnome Tweaks</strong> 程序和 “Dash to Panel” 扩展来启用它们。</p><h3 id="在-fedora-中安装-gnome-tweaks" tabindex="-1">在 Fedora 中安装 Gnome Tweaks <a class="header-anchor" href="#在-fedora-中安装-gnome-tweaks" aria-label="Permalink to “在 Fedora 中安装 Gnome Tweaks”">​</a></h3><p><strong>Gnome Tweaks</strong>，以前称为 <strong>Tweak Tool</strong>，是用于高级 GNOME 3 设置的图形界面。它主要是为 GNOME Shell 设计的，但也可以在其他桌面中使用。如果你在不同的桌面上使用 Tweaks，你可能无法拥有所有功能。它在 Fedora 的默认仓库中可用。因此，你可以使用 <code>dnf</code> 包管理器在 Fedora 上安装 Gnome Tweaks，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gnome-tweaks</span></span></code></pre></div><p>如果你使用 Fedora Silverblue，你需要使用以下命令进入你的 toolbox 容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ toolbox enter</span></span></code></pre></div><p>然后按照前面的命令安装 Tweaks。</p><h3 id="在浏览器中添加-gnome-shell-集成插件" tabindex="-1">在浏览器中添加 Gnome Shell 集成插件 <a class="header-anchor" href="#在浏览器中添加-gnome-shell-集成插件" aria-label="Permalink to “在浏览器中添加 Gnome Shell 集成插件”">​</a></h3><p>确保你在浏览器中添加了 “Gnome Shell 集成” 插件。此扩展提供与 GNOME shell 和相应扩展仓库的集成。</p><p>如果你尚未添加它，请转到插件页并搜索并安装它。</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/05/Add-Gnome-Shell-Integration-Add-on-In-Firefox-Browser.png" alt="Add Gnome Shell Integration Add-on In Firefox Browser"></p><p>将出现一个弹出窗口。单击“添加”以启用加载项。添加此扩展程序后，你将在浏览器的工具栏上看到 GNOME 图标。</p><h3 id="在-fedora-中启用-dash-到面板扩展" tabindex="-1">在 Fedora 中启用 Dash 到面板扩展 <a class="header-anchor" href="#在-fedora-中启用-dash-到面板扩展" aria-label="Permalink to “在 Fedora 中启用 Dash 到面板扩展”">​</a></h3><p>“Dash to panel” 扩展是 Gnome Shell 的图标任务栏。此扩展将 dash 移动到 GNOME 主面板中，以便将应用启动器和系统托盘组合到一个面板中，类似于 KDE Plasma 和 Windows 7 以上操作系统中的面板。</p><p>“Dash to panel” 扩展为你提供了一个永久可见的面板，其中包含最喜欢的快捷方式。因此，不再需要单独的停靠区来轻松访问正在运行和收藏的应用。</p><p>要启用 “Dash to panel” 扩展，请进入 GNOME 扩展站点并搜索 “Dash to panel” 扩展。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Search-for-Dash-to-panel-extension-in-Gnome-extensions-site.png" alt="Search for Dash to panel extension in Gnome extensions site"></p><p>单击搜索结果中的 “Dash to panel” 链接。你将被重定向到 “Dash to panel” 扩展的官方页面。点击 “ON” 按钮。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Enable-Dash-to-panel-extension.png" alt="Enable Dash to panel extension"></p><p>在下一个窗口中，单击安装按钮以启用 “Dash to panel” 扩展。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Install-Dash-to-panel-extension.png" alt="Install Dash to panel extension"></p><p>激活此扩展程序后，你将在底部看到 Dash 面板以及你最喜欢的快捷方式。</p><h3 id="在-fedora-中启用最小化和最大化按钮" tabindex="-1">在 Fedora 中启用最小化和最大化按钮 <a class="header-anchor" href="#在-fedora-中启用最小化和最大化按钮" aria-label="Permalink to “在 Fedora 中启用最小化和最大化按钮”">​</a></h3><p>打开 Gnome Tweaks 应用。进入 “<ruby>窗口标题栏<rt>Windows Titlebars</rt></ruby>” 并打开最小/最大按钮。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Enable-Minimize-And-Maximize-Buttons-In-Application-Windows-In-Fedora.png" alt="Enable minimize and maximize buttons in application windows in Fedora"></p><p>当你打开开关后，最小化和最大化按钮将出现在所有应用的窗口中。</p><p><img src="https://ostechnix.com/wp-content/uploads/2021/01/Minimize-maximize-buttons-appears-in-applications-windows-in-Fedora.png" alt="Minimize, maximize buttons appears in applications windows in Fedora"></p><p>默认情况下，最小/最大按钮在右侧可见。你可以将其位置更改为左侧或右侧。</p><p>“Dash to panel” 扩展有很多微调和自定义选项。右键单击 Dash 面板并选择设置选项，然后根据你的喜好开始对其进行自定义。</p><h3 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to “资源”">​</a></h3>',38)),s("blockquote",null,[s("p",null,[s("strong",null,[o(t,{href:"https://extensions.gnome.org/extension/1160/dash-to-panel/"},{default:n(()=>[...e[0]||(e[0]=[a("Dash to panel 网站",-1)])]),_:1})])])]),e[17]||(e[17]=s("hr",null,null,-1)),s("p",null,[e[2]||(e[2]=a("via: ",-1)),o(t,{href:"https://ostechnix.com/how-to-enable-minimize-and-maximize-buttons-in-fedora/"},{default:n(()=>[...e[1]||(e[1]=[a("https://ostechnix.com/how-to-enable-minimize-and-maximize-buttons-in-fedora/",-1)])]),_:1})]),s("p",null,[e[7]||(e[7]=a("作者：",-1)),o(t,{href:"https://ostechnix.com/author/sk/"},{default:n(()=>[...e[3]||(e[3]=[a("sk",-1)])]),_:1}),e[8]||(e[8]=a(" 选题：",-1)),o(t,{href:"https://github.com/lkxed"},{default:n(()=>[...e[4]||(e[4]=[a("lkxed",-1)])]),_:1}),e[9]||(e[9]=a(" 译者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:n(()=>[...e[5]||(e[5]=[a("geekpi",-1)])]),_:1}),e[10]||(e[10]=a(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[6]||(e[6]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=a("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原创编译，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[a("Linux中国",-1)])]),_:1}),e[15]||(e[15]=a(" 荣誉推出",-1))])])}const c=i(h,[["render",m]]);export{T as __pageData,c as default};
